import yaml

with open('/home/ubuntu/.agent-ml-research-idea_gen_0509_14/projects/distill_sparse_swiglu/registry.yaml', 'r') as f:
    data = yaml.safe_load(f)

# Search for KL-related experiments
kl_experiments = {}
for exp_id, exp_data in data.get('experiments', {}).items():
    if any(term in exp_id.lower() for term in ['kl', 'predictor', 'spon', 'ste']):
        gpu_hours = exp_data.get('reproduce', {}).get('gpu_hours')
        if gpu_hours is not None:
            kl_experiments[exp_id] = {
                'gpu_hours': gpu_hours,
                'status': exp_data.get('status'),
                'loss_type': exp_data.get('spec', {}).get('loss_type')
            }

# Sort by gpu_hours descending
for exp_id, info in sorted(kl_experiments.items(), key=lambda x: x[1]['gpu_hours'], reverse=True):
    print(f"{exp_id}: {info['gpu_hours']} hours (status: {info['status']}, loss: {info['loss_type']})")
